import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { motion, AnimatePresence } from 'framer-motion';
import { Package, CheckCircle, Clock, XCircle, MapPin } from 'lucide-react';
import toast from 'react-hot-toast';
import orderService from '../../services/orderService';
import StatusBadge from '../../components/datadisplay/StatusBadge';
import ConfirmDialog from '../../components/feedback/ConfirmDialog';

const OrdersQueue = () => {
    const [activeTab, setActiveTab] = useState('all');
    const [confirmAction, setConfirmAction] = useState(null);
    const queryClient = useQueryClient();

    const { data, isLoading } = useQuery({
        queryKey: ['sales-rep-orders', activeTab],
        queryFn: () => orderService.getAllOrders({
            status: activeTab === 'all' ? undefined : activeTab
        })
    });

    const statusMutation = useMutation({
        mutationFn: ({ orderId, status }) => orderService.updateOrderStatus(orderId, status),
        onSuccess: () => {
            toast.success('Order status updated');
            queryClient.invalidateQueries(['sales-rep-orders']);
            setConfirmAction(null);
        },
        onError: (error) => {
            toast.error(error.response?.data?.message || 'Failed to update status');
        }
    });

    const tabs = [
        { key: 'all', label: 'All', icon: Package },
        { key: 'assigned', label: 'New', icon: Clock },
        { key: 'confirmed', label: 'Confirmed', icon: CheckCircle },
        { key: 'processing', label: 'Processing', icon: Clock },
    ];

    const getNextAction = (status) => {
        const actions = {
            assigned: { action: 'confirmed', label: 'Confirm Order', color: 'bg-indigo-600 hover:bg-indigo-700' },
            confirmed: { action: 'processing', label: 'Start Processing', color: 'bg-amber-600 hover:bg-amber-700' },
            processing: { action: null, label: 'Awaiting Dispatch', color: '' }
        };
        return actions[status];
    };

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Orders Queue</h1>
                <p className="text-gray-500 dark:text-gray-400 mt-1">
                    Manage and process your assigned orders
                </p>
            </div>

            {/* Tabs */}
            <div className="flex gap-2 flex-wrap">
                {tabs.map((tab) => (
                    <button
                        key={tab.key}
                        onClick={() => setActiveTab(tab.key)}
                        className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all ${activeTab === tab.key
                                ? 'bg-indigo-600 text-white shadow-lg'
                                : 'bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700 border border-gray-200 dark:border-gray-700'
                            }`}
                    >
                        <tab.icon className="h-4 w-4" />
                        {tab.label}
                    </button>
                ))}
            </div>

            {/* Orders List */}
            <div className="space-y-4">
                {isLoading ? (
                    <div className="text-center py-12">
                        <div className="w-8 h-8 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin mx-auto" />
                    </div>
                ) : data?.data?.length === 0 ? (
                    <div className="text-center py-12 bg-white dark:bg-gray-800 rounded-xl">
                        <Package className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                        <p className="text-gray-500 dark:text-gray-400">No orders in this queue</p>
                    </div>
                ) : (
                    <AnimatePresence>
                        {data?.data?.map((order, index) => (
                            <motion.div
                                key={order.id}
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                exit={{ opacity: 0, x: -100 }}
                                transition={{ delay: index * 0.05 }}
                                className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6"
                            >
                                <div className="flex flex-col sm:flex-row sm:items-center gap-4">
                                    {/* Product Info */}
                                    <div className="flex items-center gap-4 flex-1">
                                        <div className="h-16 w-16 rounded-lg bg-gray-100 dark:bg-gray-700 overflow-hidden flex-shrink-0">
                                            {order.productImage ? (
                                                <img src={order.productImage} alt={order.productName} className="h-full w-full object-cover" />
                                            ) : (
                                                <Package className="h-full w-full p-3 text-gray-400" />
                                            )}
                                        </div>
                                        <div>
                                            <h3 className="font-semibold text-gray-900 dark:text-white">
                                                {order.productName}
                                            </h3>
                                            <div className="flex items-center gap-2 mt-1">
                                                <StatusBadge status={order.status} />
                                                <span className="text-sm text-gray-500">
                                                    Qty: {order.quantity}
                                                </span>
                                            </div>
                                            <div className="flex items-center gap-1 mt-1 text-sm text-gray-500">
                                                <MapPin className="h-3.5 w-3.5" />
                                                {order.customer?.city}, {order.customer?.state}
                                            </div>
                                        </div>
                                    </div>

                                    {/* Order Details */}
                                    <div className="text-right">
                                        <p className="text-2xl font-bold text-gray-900 dark:text-white">
                                            ${order.totalAmount.toFixed(2)}
                                        </p>
                                        <p className="text-sm text-gray-500">
                                            {new Date(order.createdAt).toLocaleDateString()}
                                        </p>
                                    </div>

                                    {/* Action Button */}
                                    {getNextAction(order.status)?.action && (
                                        <button
                                            onClick={() => setConfirmAction({
                                                orderId: order.id,
                                                status: getNextAction(order.status).action,
                                                label: getNextAction(order.status).label
                                            })}
                                            className={`px-4 py-2 text-white rounded-lg font-medium transition-colors ${getNextAction(order.status).color
                                                }`}
                                        >
                                            {getNextAction(order.status).label}
                                        </button>
                                    )}

                                    {/* Cancel Button */}
                                    {['assigned', 'confirmed'].includes(order.status) && (
                                        <button
                                            onClick={() => setConfirmAction({
                                                orderId: order.id,
                                                status: 'cancelled',
                                                label: 'Cancel Order'
                                            })}
                                            className="px-4 py-2 text-rose-600 hover:bg-rose-50 rounded-lg font-medium transition-colors"
                                        >
                                            <XCircle className="h-5 w-5" />
                                        </button>
                                    )}
                                </div>
                            </motion.div>
                        ))}
                    </AnimatePresence>
                )}
            </div>

            {/* Confirmation Dialog */}
            <ConfirmDialog
                isOpen={!!confirmAction}
                onClose={() => setConfirmAction(null)}
                onConfirm={() => statusMutation.mutate(confirmAction)}
                title="Update Order Status"
                message={`Are you sure you want to ${confirmAction?.label?.toLowerCase()}?`}
                confirmText="Confirm"
                loading={statusMutation.isLoading}
            />
        </div>
    );
};

export default OrdersQueue;
